{
  "name": "fast-json-stringify",
  "version": "7.2.0",
  "description": "Stringify your JSON at max speed",
  "main": "index.js",
  "type": "commonjs",
  "types": "types/index.d.ts",
  "scripts": {
    "bench": "node --expose-gc ./benchmark/bench.js",
    "bench:cmp": "node ./benchmark/bench-cmp-branch.js",
    "bench:cmp:ci": "node ./benchmark/bench-cmp-branch.js --ci",
    "benchmark": "node --expose-gc ./benchmark/bench-cmp-lib.js",
    "lint": "eslint",
    "lint:fix": "eslint --fix",
    "test:typescript": "tstyche",
    "test:unit": "c8 --100 --all --include=index.js --include=lib/**/*.js --exclude=lib/schema-validator.js node --test",
    "test": "npm run test:unit && npm run test:typescript"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fastify/fast-json-stringify.git"
  },
  "keywords": [
    "json",
    "stringify",
    "schema",
    "fast"
  ],
  "author": "Matteo Collina <hello@matteocollina.com>",
  "contributors": [
    {
      "name": "Tomas Della Vedova",
      "url": "https://delvedor.dev"
    },
    {
      "name": "Aras Abbasi",
      "email": "aras.abbasi@gmail.com"
    },
    {
      "name": "Manuel Spigolon",
      "email": "behemoth89@gmail.com"
    },
    {
      "name": "Frazer Smith",
      "email": "frazer.dev@icloud.com",
      "url": "https://github.com/fdawgs"
    }
  ],
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/fastify/fast-json-stringify/issues"
  },
  "homepage": "https://github.com/fastify/fast-json-stringify#readme",
  "funding": [
    {
      "type": "github",
      "url": "https://github.com/sponsors/fastify"
    },
    {
      "type": "opencollective",
      "url": "https://opencollective.com/fastify"
    }
  ],
  "devDependencies": {
    "c8": "^12.0.0",
    "cli-select": "^1.1.2",
    "compile-json-stringify": "^0.1.2",
    "eslint": "^9.39.2",
    "fast-json-stringify": ".",
    "json-accelerator": "^0.1.7",
    "neostandard": "^0.13.0",
    "simple-git": "^4.0.2",
    "tinybench": "^6.0.0",
    "tstyche": "^7.1.0",
    "typebox": "^1.0.81",
    "typescript": "~6.0.2",
    "webpack": "^5.104.1"
  },
  "dependencies": {
    "@fastify/merge-json-schemas": "^0.2.0",
    "ajv": "^8.12.0",
    "ajv-formats": "^3.0.1",
    "fast-uri": "^4.0.0",
    "json-schema-ref-resolver": "^3.0.0",
    "rfdc": "^1.2.0"
  },
  "runkitExampleFilename": "./examples/example.js"
}
